class DiagnosisProbe:
    def run_full_diagnosis(train_loader):
        previous_mode = view.model.training
        view.model.eval()
        try:
            with no_grad():
                collect_existing_embedding_and_all_position_margin_metrics()
                for _, sequence, positive, negative in bounded_batches(train_loader):
                    t = largest_nonzero_index_per_row(sequence)
                    valid = valid_final_targets(t, positive, negative)
                    targets = paired_items_at_original_t(positive, negative, t)
                    base = paired_margin_at_last_nonpadding(sequence, targets)
                    for control in [shuffle_prefix_keep_last,
                                    remove_recent_nonfinal,
                                    remove_equal_size_oldest]:
                        changed, support = control(sequence, local_rng_seed_42)
                        changed = left_pad_valid_events(changed)
                        margin = paired_margin_at_last_nonpadding(changed, targets)
                        record_paired_deltas_and_reversals(base, margin, valid & support)
                    check_future_changes_leave_interior_features_unchanged(sequence)
                return {'metrics': summarize_with_support_and_nulls(),
                        'metric_definitions': explicit_definitions_and_limits()}
        finally:
            view.model.train(previous_mode)

def diagnosis_interpreter_prompt(raw_diagnosis):
    return prompt_with_metrics_definitions_and_instruction_to_separate_measurements_from_hypotheses(raw_diagnosis)
